#include <iostream>
#include <fstream>
#include <vector>
#include <cstdlib>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> tab;
    int x;
    while (plik >> x) tab.push_back(x);

    int sumaPar = 0, roznicaPar = 0;
    for (int i = 0; i < (int)tab.size() - 1; i++) {
        if (tab[i] + tab[i+1] > 20) sumaPar++;
        if (abs(tab[i] - tab[i+1]) > 10) roznicaPar++;
    }
    cout << "a) Pary z suma > 20: " << sumaPar << endl;
    cout << "b) Pary z roznica > 10: " << roznicaPar << endl;
    return 0;
}
```

**Wyjasnienie**: Wczytujemy wszystkie liczby do wektora, potem iterujemy po parach sasiadow. Dla kazdej pary sprawdzamy dwa warunki niezaleznie.

